edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	const parts: string[] = [];
	const files: string[] = [];
	if (!input.includesFamilyShared && input.family !== "pi-default") {
		const shared = familySharedBody(input.family, input.root).trim();
		if (shared) {
			if (!rolePrompt.includes(shared)) parts.push(shared);
			files.push(`${input.family}/shared.md`);
		}
	}
	if (rolePrompt) {
		parts.push(rolePrompt);
		files.push("role");
	}
	if (input.common && input.family !== "pi-default") {
		const common = commonBody(input.root).trim();
		if (common && !rolePrompt.includes(common)) {
			parts.push(common);
			files.push("common.md");
		}
	}
	return {
		family: input.family,
		text: parts.join("\n"),
		files,
	};
}

edits.oldText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}

